<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\SoftDeletes;use Illuminate\Support\Str;class PortfolioItem extends Model{use SoftDeletes;public $incrementing=false;protected $keyType='string';protected $fillable=['category_id','title','short_description','description','cover_image','status','created_by'];protected static function booted(){static::creating(fn($m)=>$m->id??=(string)Str::uuid());}public function category(){return $this->belongsTo(PortfolioCategory::class,'category_id');}public function media(){return $this->hasMany(PortfolioMedia::class,'portfolio_id')->orderBy('sort_order');}}
